-- MSS Fleet Intelligence - Stage 1 schema (MySQL 8 / MariaDB 10.4+). Non-destructive: IF NOT EXISTS only.
CREATE DATABASE IF NOT EXISTS mss_fleet_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mss_fleet_management;
CREATE TABLE IF NOT EXISTS roles(id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO roles(slug,name) VALUES('super_admin','Super Admin'),('fleet_manager','Fleet Manager'),('operations','Operations / Trip Staff'),('maintenance','Maintenance Staff'),('accounts','Accounts Staff'),('readonly','Management Read-only');
CREATE TABLE IF NOT EXISTS branches(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, city VARCHAR(80), is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY, role_id INT NOT NULL, branch_id INT NULL, name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts(id INT AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(45) NOT NULL, email VARCHAR(160), attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(ip,attempted_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS drivers(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, mobile VARCHAR(20), licence_no VARCHAR(40) UNIQUE, licence_expiry DATE NULL, branch_id INT NULL, availability ENUM('available','on_trip','leave','inactive') NOT NULL DEFAULT 'available', deleted_at DATETIME NULL, INDEX(licence_expiry), FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicles(id INT AUTO_INCREMENT PRIMARY KEY, reg_no VARCHAR(20) NOT NULL UNIQUE, fleet_no VARCHAR(40), vehicle_type ENUM('bus','van','truck','car','bike','other') NOT NULL, make VARCHAR(60), model VARCHAR(60), mfg_year SMALLINT, fuel_type ENUM('diesel','petrol','cng','electric','other') NOT NULL DEFAULT 'diesel', ownership ENUM('owned','leased','hired') NOT NULL DEFAULT 'owned',
 chassis_no VARCHAR(40) NULL UNIQUE, engine_no VARCHAR(40), seating_capacity SMALLINT NULL, load_capacity_kg INT NULL, axle_count TINYINT NULL, body_type VARCHAR(60), odometer INT UNSIGNED NOT NULL DEFAULT 0, expected_kmpl DECIMAL(6,2) NULL,
 branch_id INT NULL, driver_id INT NULL, status ENUM('available','on_trip','reserved','maintenance','accident_hold','inactive','disposed') NOT NULL DEFAULT 'available',
 gps_provider VARCHAR(60) NULL, gps_device_id VARCHAR(60) NULL, gps_lat DECIMAL(10,7) NULL, gps_lng DECIMAL(10,7) NULL, gps_updated_at DATETIME NULL,
 insurance_expiry DATE NULL, permit_expiry DATE NULL, fitness_expiry DATE NULL, road_tax_expiry DATE NULL, puc_expiry DATE NULL, next_service_date DATE NULL, next_service_km INT UNSIGNED NULL,
 remarks TEXT, deleted_at DATETIME NULL, created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(vehicle_type),INDEX(status),INDEX(branch_id),INDEX(insurance_expiry),INDEX(deleted_at),
 FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trips(id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, driver_id INT NULL, origin VARCHAR(120), destination VARCHAR(120), planned_departure DATETIME, planned_arrival DATETIME, actual_departure DATETIME NULL, actual_arrival DATETIME NULL, start_odo INT UNSIGNED NULL, end_odo INT UNSIGNED NULL,
 distance_km BIGINT GENERATED ALWAYS AS (CAST(end_odo AS SIGNED) - CAST(start_odo AS SIGNED)) STORED,
 status ENUM('scheduled','in_progress','completed','cancelled','delayed') NOT NULL DEFAULT 'scheduled', CHECK (end_odo IS NULL OR start_odo IS NULL OR end_odo>=start_odo), INDEX(planned_departure),INDEX(status),
 FOREIGN KEY(vehicle_id) REFERENCES vehicles(id), FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fuel_entries(id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, filled_at DATETIME NOT NULL, litres DECIMAL(8,2) NOT NULL, price_per_litre DECIMAL(8,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, odometer INT UNSIGNED NOT NULL, is_full_tank TINYINT(1) NOT NULL DEFAULT 1, vendor VARCHAR(120), receipt_no VARCHAR(60), payment_method VARCHAR(30), INDEX(filled_at), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS maintenance_records(id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, service_type ENUM('preventive','routine','repair','emergency','accident_repair','tyre_related') NOT NULL, complaint VARCHAR(255), work_performed TEXT, service_date DATE NOT NULL, odometer INT UNSIGNED NULL, next_service_date DATE NULL, next_service_km INT UNSIGNED NULL, workshop VARCHAR(120), parts_cost DECIMAL(12,2) NOT NULL DEFAULT 0, labour_cost DECIMAL(12,2) NOT NULL DEFAULT 0, other_cost DECIMAL(12,2) NOT NULL DEFAULT 0, total_cost DECIMAL(12,2) NOT NULL DEFAULT 0, invoice_no VARCHAR(60), status ENUM('open','completed') NOT NULL DEFAULT 'completed', notes TEXT, INDEX(service_date), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB;
-- Ledger rule: Fuel and Maintenance costs live in their own tables; expenses must NOT duplicate them (dashboard avoids double counting).
CREATE TABLE IF NOT EXISTS expenses(id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NULL, expense_date DATE NOT NULL, category ENUM('tyres','toll','parking','insurance','road_tax','permit','driver_allowance','loan_emi','other') NOT NULL, amount DECIMAL(12,2) NOT NULL, description VARCHAR(255), approval_status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', approved_by INT NULL, approved_at DATETIME NULL, INDEX(expense_date), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(60) NOT NULL, entity VARCHAR(60), entity_id INT NULL, details TEXT, ip VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(entity,entity_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS system_settings(k VARCHAR(60) PRIMARY KEY, v VARCHAR(255)) ENGINE=InnoDB;
INSERT IGNORE INTO system_settings VALUES('expiry_warn_days','30');

-- ===== Stage 2-4 tables =====
CREATE TABLE IF NOT EXISTS routes(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, origin VARCHAR(120), destination VARCHAR(120), distance_km INT UNSIGNED NULL, deleted_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vendors(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, vendor_type VARCHAR(40), phone VARCHAR(20), deleted_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicle_documents(id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NULL, driver_id INT NULL, doc_type ENUM('rc','insurance','permit','fitness','road_tax','puc','driver_licence','other') NOT NULL, doc_number VARCHAR(60), issue_date DATE NULL, expiry_date DATE NULL, file_path VARCHAR(120) NULL, uploaded_by INT NULL, notes VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME NULL, INDEX(expiry_date), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id), FOREIGN KEY(driver_id) REFERENCES drivers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trip_expenses(id INT AUTO_INCREMENT PRIMARY KEY, trip_id INT NOT NULL, category ENUM('fuel','toll','parking','driver_allowance','loading','other') NOT NULL, amount DECIMAL(12,2) NOT NULL, notes VARCHAR(255), FOREIGN KEY(trip_id) REFERENCES trips(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS driver_assignments(id INT AUTO_INCREMENT PRIMARY KEY, driver_id INT NOT NULL, vehicle_id INT NOT NULL, start_date DATE NOT NULL, end_date DATE NULL, notes VARCHAR(255), FOREIGN KEY(driver_id) REFERENCES drivers(id), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS breakdown_records(id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, breakdown_date DATETIME NOT NULL, location VARCHAR(160), description TEXT, downtime_hours DECIMAL(7,1) NULL, towing_cost DECIMAL(12,2) NOT NULL DEFAULT 0, repair_cost DECIMAL(12,2) NOT NULL DEFAULT 0, resolution TEXT, status ENUM('open','resolved') NOT NULL DEFAULT 'open', FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicle_loans(id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, lender VARCHAR(120) NOT NULL, account_ref VARCHAR(60), principal DECIMAL(14,2) NOT NULL, interest_rate DECIMAL(5,2) NULL, emi_amount DECIMAL(12,2) NOT NULL, start_date DATE, end_date DATE, instalments SMALLINT, deleted_at DATETIME NULL, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS loan_payments(id INT AUTO_INCREMENT PRIMARY KEY, loan_id INT NOT NULL, paid_on DATE NOT NULL, amount DECIMAL(12,2) NOT NULL, reference VARCHAR(60), FOREIGN KEY(loan_id) REFERENCES vehicle_loans(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tyres(id INT AUTO_INCREMENT PRIMARY KEY, tyre_code VARCHAR(40) NOT NULL UNIQUE, brand VARCHAR(60), size VARCHAR(30), tyre_type VARCHAR(30), serial_no VARCHAR(60), purchase_date DATE NULL, supplier VARCHAR(120), invoice_no VARCHAR(60), purchase_price DECIMAL(12,2) NULL, condition_note VARCHAR(120), status ENUM('in_stock','fitted','under_inspection','under_retreading','reusable','scrapped','sold') NOT NULL DEFAULT 'in_stock', deleted_at DATETIME NULL, INDEX(status)) ENGINE=InnoDB;
-- active_key is 1 while a fitment is open, NULL once removed: UNIQUE keys on it make duplicate active fitments impossible at DB level.
CREATE TABLE IF NOT EXISTS tyre_fitments(id INT AUTO_INCREMENT PRIMARY KEY, tyre_id INT NOT NULL, vehicle_id INT NOT NULL, position VARCHAR(20) NOT NULL, fitted_on DATE NOT NULL, odo_fitted INT UNSIGNED NULL, removed_on DATE NULL, odo_removed INT UNSIGNED NULL, removal_reason VARCHAR(160),
 active_key TINYINT GENERATED ALWAYS AS (CASE WHEN removed_on IS NULL THEN 1 ELSE NULL END) STORED, UNIQUE KEY uq_tyre_active(tyre_id,active_key), UNIQUE KEY uq_pos_active(vehicle_id,position,active_key), FOREIGN KEY(tyre_id) REFERENCES tyres(id), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tyre_inspections(id INT AUTO_INCREMENT PRIMARY KEY, tyre_id INT NOT NULL, inspected_on DATE NOT NULL, tread_mm DECIMAL(4,1) NULL, condition_note VARCHAR(160), notes VARCHAR(255), FOREIGN KEY(tyre_id) REFERENCES tyres(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tyre_retreading(id INT AUTO_INCREMENT PRIMARY KEY, tyre_id INT NOT NULL, sent_on DATE NOT NULL, returned_on DATE NULL, vendor VARCHAR(120), cost DECIMAL(12,2) NULL, FOREIGN KEY(tyre_id) REFERENCES tyres(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tyre_disposals(id INT AUTO_INCREMENT PRIMARY KEY, tyre_id INT NOT NULL, disposal_type ENUM('scrap','sale') NOT NULL, disposed_on DATE NOT NULL, reason VARCHAR(160), buyer VARCHAR(120), sale_amount DECIMAL(12,2) NULL, reference VARCHAR(60), approved_by INT NULL, FOREIGN KEY(tyre_id) REFERENCES tyres(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tyre_movements(id INT AUTO_INCREMENT PRIMARY KEY, tyre_id INT NOT NULL, action VARCHAR(20) NOT NULL, vehicle_id INT NULL, position VARCHAR(20), moved_at DATETIME DEFAULT CURRENT_TIMESTAMP, user_id INT NULL, note VARCHAR(160), INDEX(tyre_id), FOREIGN KEY(tyre_id) REFERENCES tyres(id)) ENGINE=InnoDB;
